}

contracts/markets/PairVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC4626} from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {IPairVault} from "../interfaces/IPairVault.sol";
import {IMarketVaultAccounting} from "../interfaces/IMarketVaultAccounting.sol";

/// @title PairVault — ERC-4626 USDC vault for one lending pair
/// @notice Idle USDC sits here. Market pulls on borrow and pushes on repay.
///         `totalAssets` = idle balance + principal/interest owed by the market.
contract PairVault is ERC4626, IPairVault {
    using SafeERC20 for IERC20;

    address public immutable override market;
    bytes32 public immutable override pairId;

    error NotMarket(address caller);
    error ZeroAddress();
    error InsufficientIdle(uint256 requested, uint256 idle);

    modifier onlyMarket() {
        if (msg.sender != market) revert NotMarket(msg.sender);
        _;
    }

    constructor(
        IERC20 asset_,
        address market_,
        bytes32 pairId_,
        string memory name_,
        string memory symbol_
    ) ERC20(name_, symbol_) ERC4626(asset_) {
        if (market_ == address(0)) revert ZeroAddress();
        market = market_;
        pairId = pairId_;
    }

    /// @inheritdoc IPairVault
    function idleAssets() public view override returns (uint256) {
        return IERC20(asset()).balanceOf(address(this));
    }

    /// @inheritdoc ERC4626
    function totalAssets() public view override(ERC4626, IERC4626) returns (uint256) {
        return idleAssets() + IMarketVaultAccounting(market).assetsOwedToVault(pairId);
    }

    /// @dev Lenders can only withdraw idle cash, not assets currently lent out.
    function maxWithdraw(address owner_) public view override(ERC4626, IERC4626) returns (uint256) {
        uint256 ownerAssets = _convertToAssets(balanceOf(owner_), Math.Rounding.Floor);
        uint256 idle = idleAssets();
        return ownerAssets < idle ? ownerAssets : idle;
    }

    function maxRedeem(address owner_) public view override(ERC4626, IERC4626) returns (uint256) {
        return _convertToShares(maxWithdraw(owner_), Math.Rounding.Floor);
    }

    /// @inheritdoc IPairVault
    function pullLiquidity(uint256 assets, address to) external override onlyMarket {
        if (assets == 0) return;
        uint256 idle = idleAssets();
        if (assets > idle) revert InsufficientIdle(assets, idle);
        IERC20(asset()).safeTransfer(to, assets);
    }

    /// @inheritdoc IPairVault
    function pushLiquidity(uint256 assets) external override onlyMarket {
        if (assets == 0) return;
        IERC20(asset()).safeTransferFrom(msg.sender, address(this), assets);
    }
}

contracts/markets/PairVaultFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {PairVault} from "./PairVault.sol";
import {IMarketVaultRegistry} from "../interfaces/IMarketVaultRegistry.sol";

/// @notice Deploys one PairVault per pairId and registers it on the market.
contract PairVaultFactory is Ownable {
    IERC20 public immutable asset;
    IMarketVaultRegistry public immutable market;

    mapping(bytes32 => address) public vaultOf;

    event VaultCreated(bytes32 indexed pairId, address indexed vault, string name, string symbol);

    error VaultExists(bytes32 pairId);
    error ZeroAddress();

    constructor(address initialOwner, address asset_, address market_) Ownable(initialOwner) {
        if (asset_ == address(0) || market_ == address(0)) revert ZeroAddress();
        asset = IERC20(asset_);
        market = IMarketVaultRegistry(market_);
    }

    function createVault(bytes32 pairId, string calldata name_, string calldata symbol_)
        external
        onlyOwner
        returns (address vault)
    {
        if (vaultOf[pairId] != address(0)) revert VaultExists(pairId);
        PairVault v = new PairVault(asset, address(market), pairId, name_, symbol_);
        vault = address(v);
        vaultOf[pairId] = vault;
        market.setVault(pairId, vault);
        emit VaultCreated(pairId, vault, name_, symbol_);
    }
}

contracts/markets/StaticApySource.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IApySource} from "./interfaces/IApySource.sol";

/// @notice Simple owner-configured lender APY. Replace with manager contract via MarketLendingModule.setApySource.
contract StaticApySource is IApySource, Ownable {
    mapping(bytes32 => uint16) public apyBps;
    uint16 public defaultApyBps;

    event ApySet(bytes32 indexed marketId, uint16 apyBps);
    event DefaultApySet(uint16 apyBps);

    error InvalidApy();

    constructor(address initialOwner, uint16 defaultApyBps_) Ownable(initialOwner) {
        if (defaultApyBps_ > 10_000) revert InvalidApy();
        defaultApyBps = defaultApyBps_;
    }

    function setDefaultApyBps(uint16 bps) external onlyOwner {
        if (bps > 10_000) revert InvalidApy();
        defaultApyBps = bps;
        emit DefaultApySet(bps);
    }

    function setApyBps(bytes32 marketId, uint16 bps) external onlyOwner {
        if (bps > 10_000) revert InvalidApy();
        apyBps[marketId] = bps;
        emit ApySet(marketId, bps);
    }

    function getLenderApyBps(bytes32 marketId) external view returns (uint16) {
        uint16 configured = apyBps[marketId];
        return configured == 0 ? defaultApyBps : configured;
    }
}

